+/// Whether `name` can name a saved job: 1 to 64 letters, digits, `-`, `_`
+/// or `.`, not starting with `.`.
+pub fn valid_job_name(name: &str) -> bool {
+    (1..=64).contains(&name.len())
+        && !name.starts_with('.')
+        && name
+            .chars()
+            .all(|c| c.is_ascii_alphanumeric() || matches!(c, '-' | '_' | '.'))
+}
