  202: /// (JOB_LOGS jl-2, jl-3): one ID, its own log and job record, around every
  203: /// pass and `--retry` rerun; `--save` keeps the job first, `--export`
  204: /// writes it, with how the run went, after.
  205: ///
  206: /// pfc-5: the status carries the destination's per-file failure verdict —
  207: /// 0 when every file landed, 2 when the operation completed with files
  208: /// that did not. win-1: `run_with_retries` boxes each attempt, and
  209: /// `run_transfer` / `run_move` box their route dispatch, so this frame
  210: /// holds pointers rather than sessions.
  211: async fn run_command(
  212:     ctx: &AppContext,
  213:     verb: Verb,
  214:     mut args: TransferArgs,
  215:     lifecycle_trace: &TransferLifecycleTrace,
  216:     saved_job: Option<String>,
  217: ) -> Result<ExitCode> {
  218:     args.run = crate::run_log::CommandRun::start(verb.word(), &args, saved_job).await;
  219:     let run = args.run.clone();
  220:     if let Some(name) = &args.save {
  221:         let run = run.as_ref().ok_or_else(|| {
  222:             eyre::eyre!("this command cannot be saved as a job: it has no run ID")
  223:         })?;
  224:         if let Err(error) = run.save_as(name, args.json).await {
  225:             run.finish(&Err(eyre::eyre!("{error:#}"))).await;
  226:             return Err(error);
  227:         }
  228:     }
  229:     let wait = Duration::from_secs(args.wait);
  230:     let result = run_with_retries(
  231:         args.retry,
  232:         wait,
  233:         |_n| -> Pin<Box<dyn Future<Output = Result<ExitCode>> + '_>> {
  234:             match verb {
  235:                 Verb::Copy => Box::pin(run_transfer(
  236:                     ctx,
  237:                     &args,
  238:                     TransferKind::Copy,
  239:                     lifecycle_trace,
  240:                 )),
  241:                 Verb::Mirror => Box::pin(run_transfer(
  242:                     ctx,
  243:                     &args,
  244:                     TransferKind::Mirror,
  245:                     lifecycle_trace,
  246:                 )),
  247:                 Verb::Move => Box::pin(run_move(ctx, &args, lifecycle_trace)),
  248:             }
  249:         },
  250:     )
  251:     .await;
  252:     if let Some(run) = &run {
  253:         run.finish(&result).await;
  254:         if let Some(file) = &args.export {
  255:             if let Err(error) = run.export_to(file, args.json).await {
  256:                 // The transfer's own error comes first; this one is said.
  257:                 match &result {
  258:                     Ok(_) => return Err(error),
  259:                     Err(_) => eprintln!("blit: {error:#}"),
  260:                 }
  261:             }
  262:         }
  263:     } else if args.export.is_some() {
  264:         eyre::bail!("this command's job cannot be exported: it has no run ID");
  265:     }
  266:     result
  267: }
